/**
 * Applies a discount to a cart total.
 *
 * @param cart - Cart with at least one line item; empty carts are a programmer error upstream.
 * @param code - Discount code, already normalized by the caller.
 * @returns `Result<Cart, DiscountError>` — `err({ type: 'invalid_code' })` when `code` is unknown.
 * @throws {InvariantError} if `cart.items` is empty — callers must guard this before invoking.
 */
function applyDiscount(cart: Cart, code: string): Result<Cart, DiscountError> {
	invariant(cart.items.length > 0, 'applyDiscount called with empty cart');

	const discount = lookupDiscount(code);
	if (!discount) {
		return err({ type: 'invalid_code', code });
	}

	return ok({ ...cart, total: cart.total - discount.amount });
}
```

`@throws` marks programmer error only (InvariantError), never Result's recoverable path — that's covered by `@returns`. No `@example`: usage isn't non-obvious here.

